    if (!function_exists('aitfGetNotificationSentInfo')) {
        function aitfGetNotificationSentInfo($db, $serviceUniversalId, $actionNames)
        {
            if (empty($serviceUniversalId) || empty($actionNames) || !$db) {
                return null;
            }
            if (!is_array($actionNames)) {
                $actionNames = array($actionNames);
            }
            try {
                $inClause = implode(',', array_fill(0, count($actionNames), '?'));
                $params = array_merge(array($serviceUniversalId), $actionNames);
                // Check dedicated audit_notification_sent_log first
                $sql = "SELECT id as action_id, action, sent_date, status 
                        FROM audit_notification_sent_log 
                        WHERE service_id = ? AND action IN ($inClause) AND status = 'sent' AND (is_deleted = 'N' OR is_deleted IS NULL) 
                        ORDER BY id DESC LIMIT 1";
                $stmt = $db->prepare($sql);
                $stmt->execute($params);
                $res = $stmt->fetch(PDO::FETCH_ASSOC);
                if ($res) {
                    return $res;
                }
                // Fallback to ca_service_dates if needed
                $sql2 = "SELECT action_id, action, due_date, sent_date, status 
                         FROM ca_service_dates 
                         WHERE service_id = ? AND action IN ($inClause) AND status = 'sent' AND (is_deleted = 'N' OR is_deleted IS NULL) 
                         ORDER BY action_id DESC LIMIT 1";
                $stmt2 = $db->prepare($sql2);
                $stmt2->execute($params);
                $res2 = $stmt2->fetch(PDO::FETCH_ASSOC);
                return $res2 ?: null;
            } catch (Throwable $e) {
                return null;
            }
        }
    }

    if (!function_exists('aitfFormatNotificationSentDate')) {
        function aitfFormatNotificationSentDate($dateStr)
        {
            if (empty($dateStr)) {
                return '';
            }
            $ts = strtotime($dateStr);
            if (!$ts) {
                return '';
            }
            if (date('H:i:s', $ts) === '00:00:00') {
                return date('d.m.Y', $ts);
            }
            return date('d.m.Y h:i A', $ts);
        }
    }

    if (!function_exists('aitfGetCertificateSentInfo')) {
        function aitfGetCertificateSentInfo($db, $serviceUniversalId, $stage = '', $customerId = null)
        {
            if (!$db) {
                return null;
            }
            try {
                if (!empty($serviceUniversalId)) {
                    if (!empty($stage)) {
                        $sql = "SELECT id, service_id, customer_id, stage, sent_date, recipient_email, sent_by, status 
                                FROM certificate_sent_log 
                                WHERE service_id = ? AND stage = ? AND status = 'sent' AND (is_deleted = 'N' OR is_deleted IS NULL) 
                                ORDER BY id DESC LIMIT 1";
                        $stmt = $db->prepare($sql);
                        $stmt->execute(array($serviceUniversalId, $stage));
                    } else {
                        $sql = "SELECT id, service_id, customer_id, stage, sent_date, recipient_email, sent_by, status 
                                FROM certificate_sent_log 
                                WHERE service_id = ? AND status = 'sent' AND (is_deleted = 'N' OR is_deleted IS NULL) 
                                ORDER BY id DESC LIMIT 1";
                        $stmt = $db->prepare($sql);
                        $stmt->execute(array($serviceUniversalId));
                    }
                    $res = $stmt->fetch(PDO::FETCH_ASSOC);
                    if ($res) {
                        return $res;
                    }
                }
                if (!empty($customerId) && !empty($stage)) {
                    $sql2 = "SELECT id, service_id, customer_id, stage, sent_date, recipient_email, sent_by, status 
                             FROM certificate_sent_log 
                             WHERE customer_id = ? AND stage = ? AND status = 'sent' AND (is_deleted = 'N' OR is_deleted IS NULL) 
                             ORDER BY id DESC LIMIT 1";
                    $stmt2 = $db->prepare($sql2);
                    $stmt2->execute(array($customerId, $stage));
                    $res2 = $stmt2->fetch(PDO::FETCH_ASSOC);
                    return $res2 ?: null;
                }
                return null;
            } catch (Throwable $e) {
                return null;
            }
        }
    }

    if (!function_exists('caDateGraphTargetForEntry')) {
