            $allSpServices = $statement->fetchAll();

            // $spRowCount = "SELECT count(*) as totalsprow FROM service_type_sp WHERE sp_customer = :id";
            $spRowCount = "SELECT * FROM service where service_type = 'SP' and customer_id = :id AND (is_deleted = 'NO' OR is_deleted IS NULL) order by service_id desc limit 1";
            $statement = $db->prepare($spRowCount);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $spCount = $statement->fetch();

            $paymentid = "SELECT * FROM payment_system_id WHERE customer_id = :id ";
            $statement = $db->prepare($paymentid);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $paymentDetails = $statement->fetch();
            $payId = $paymentDetails['payment_sy_id'];

            $payRowCount = "SELECT count(*) as totalpayrow FROM payment_system WHERE payment_sy_id = :payid";
            $statement = $db->prepare($payRowCount);
            $statement->bindParam(':payid', $payId);
            $statement->execute();
            $payCount = $statement->fetch();

            $payment_info = "SELECT * FROM payment_system WHERE payment_sy_id = :payid";
            $statement = $db->prepare($payment_info);
            $statement->bindParam(':payid', $payId);
            $statement->execute();
            $paymentInfo = $statement->fetchAll();

            $sql1 = "SELECT * FROM `service` WHERE customer_id = :id";
            $statement = $db->prepare($sql1);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $servicesDone = $statement->fetchAll();

            $customerStatus = "SELECT * FROM customer_status";
            $statement = $db->prepare($customerStatus);
            $statement->execute();
            $applicationStatusOptions = $statement->fetchAll();

            $sql = "SELECT max(service_id) as c_service FROM `service` where customer_id = :id AND (is_deleted = 'NO' OR is_deleted IS NULL)";
            $statement = $db->prepare($sql);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $letestService = $statement->fetch();

            $sqlSvcType = "SELECT `service_type` FROM `service` WHERE `service_id` = :id";
            $statement = $db->prepare($sqlSvcType);
            $statement->bindParam(':id', $letestService['c_service']);
            $statement->execute();
            $letestServiceType = $statement->fetch();

            $stmtHasCR = $db->prepare("SELECT service_id FROM `service` WHERE customer_id = :id AND service_type = 'CR' AND (is_deleted = 'NO' OR is_deleted IS NULL) LIMIT 1");
            $stmtHasCR->bindParam(':id', $_GET['customerid']);
            $stmtHasCR->execute();
            $hasActiveCR = (bool) $stmtHasCR->fetch();

            $getsvccount = "SELECT service_type from service where service_id = :id";
            $statement = $db->prepare($getsvccount);
            $statement->bindParam(':id', $id);
            $statement->execute();
            $servicetype = $statement->fetch();

            $invoice = "SELECT inv.*, 
                (SELECT GROUP_CONCAT(DISTINCT service_desc SEPARATOR ', ') FROM invoice_services WHERE invoice_ids = inv.invoice_id) AS invoice_service_type
            FROM `invoice_details` inv 
            WHERE inv.invoice_type = 'final' AND inv.customer_id = :id AND (inv.is_deleted = 'No' OR inv.is_deleted IS NULL) 
            ORDER BY inv.invoice_id ASC";
            $statement = $db->prepare($invoice);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $invoiceList = $statement->fetchAll();

            $paymentrcv = "SELECT 
                SUM(CASE WHEN (discount_amount > 0 OR service_type LIKE '%tds%' OR service_type LIKE '%discount%' OR service_type LIKE '%short%') THEN 0 ELSE payment_received END) as payment_sum,
                SUM(CASE WHEN tds_amount > 0 THEN tds_amount WHEN service_type LIKE '%tds%' THEN payment_received ELSE 0 END) as tds_sum,
                SUM(CASE WHEN discount_amount > 0 THEN discount_amount WHEN (service_type LIKE '%discount%' OR service_type LIKE '%short%') THEN payment_received ELSE 0 END) as discount_sum
                FROM `payment_system` WHERE customer_id = :id";
            $statement = $db->prepare($paymentrcv);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $paymentTotal = $statement->fetch();

            $balance = "SELECT SUM(balance) as balance_sum FROM `payment_system` WHERE customer_id = :id";
            $statement = $db->prepare($balance);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $balanceTotal = $statement->fetch();

            $invoiceRcv = "SELECT SUM(final_amount) as invoice_sum FROM `invoice_details` WHERE customer_id = :id AND invoice_type = 'final' AND (is_deleted = 'No' OR is_deleted IS NULL)";
            $statement = $db->prepare($invoiceRcv);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $invoiceTotal = $statement->fetch();

            $getSAII = "SELECT COUNT(service_id) as service_id FROM service where customer_id = :id AND service_type = 'SA-II' AND (is_deleted = 'NO' OR is_deleted IS NULL)";
            $statement = $db->prepare($getSAII);
            $statement->bindParam(":id", $_GET["customerid"]);
            $statement->execute();
            $totalSAII = $statement->fetch();

            if (!$isSupplierAccount) {
                $dateGraphData = caDateGraphBuildForCustomer($db, $_GET['customerid']);
            }
        } catch (Exception $ex) {
            echo $ex;
        }
    }
    ?>

