        .go-ai-robot-svg .go-ai-eye {
            fill: #eef2ff;
            stroke: #a855f7;
        }

        .go-ai-robot-svg .go-ai-eye-text {
            fill: #4c1d95;
            font-family: Arial, Helvetica, sans-serif;
            font-size: 7px;
            font-weight: 800;
            dominant-baseline: middle;
            text-anchor: middle;
        }

        .go-ai-robot-svg .go-ai-antenna,
        .go-ai-robot-svg .go-ai-mouth,
        .go-ai-robot-svg .go-ai-ear {
            fill: none;
            stroke: #c084fc;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .go-ai-robot-svg .go-ai-antenna-dot {
            fill: #c084fc;
        }

        @keyframes aitf-pulse-icon {

            0%,
            100% {
                opacity: 0.8;
                transform: scale(1);
            }

            50% {
                opacity: 1;
                transform: scale(1.2);
            }
        }

        .aitf-ai-header-btn {
            align-items: center;
            border-radius: 6px;
            display: inline-flex;
            gap: 6px;
            line-height: 1;
            margin-top: 0 !important;
            padding: 7px 10px !important;
        }

        .aitf-ai-done-badge {
            align-items: center;
            background: rgba(16, 185, 129, 0.18);
            border: 1px solid rgba(187, 247, 208, 0.55);
            border-radius: 999px;
            color: #ecfdf5;
            display: inline-flex;
            font-size: 11px;
            font-weight: 800;
            gap: 5px;
            letter-spacing: 0.02em;
            line-height: 1;
            padding: 6px 9px;
            text-transform: uppercase;
            white-space: nowrap;
        }

        .aitf-ai-done-badge i {
            color: #86efac;
        }

        .aitf-ai-modal {
            z-index: 100000 !important;
        }

        body.aitf-ai-review-active .modal-backdrop {
            z-index: 99999 !important;
        }

        .aitf-ai-modal .modal-dialog {
            width: min(950px, 92vw) !important;
            margin: 30px auto !important;
            z-index: 100001 !important;
        }

        .aitf-ai-modal .modal-content {
            background: #090d16;
            border: 1px solid rgba(99, 102, 241, 0.3);
            border-radius: 16px;
            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6), 0 0 40px rgba(99, 102, 241, 0.15);
            overflow: hidden;
            color: #f1f5f9;
            font-family: 'Outfit', 'Inter', system-ui, -apple-system, sans-serif;
        }

        .aitf-ai-modal .modal-header {
            background: #070a10;
            border-bottom: 1px solid rgba(99, 102, 241, 0.15);
            padding: 18px 24px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .aitf-ai-modal .modal-header .close {
            color: #94a3b8;
            opacity: 1;
            font-size: 26px;
            font-weight: 300;
            text-shadow: none;
            transition: color 0.2s, transform 0.2s;
            margin-top: 0;
            padding: 10px;
        }

        .aitf-ai-modal .modal-header .close:hover {
            color: #fff;
            transform: scale(1.1);
        }

        .aitf-ai-modal .modal-title {
            font-size: 20px;
            font-weight: 700;
            color: #f1f5f9;
            display: flex;
            align-items: center;
            gap: 10px;
            margin: 0;
        }

        .aitf-ai-modal .modal-body {
            padding: 24px;
            background: #090d16;
        }

        .aitf-ai-welcome {
            background: linear-gradient(135deg, rgba(30, 41, 59, 0.45) 0%, rgba(15, 23, 42, 0.65) 100%);
            border: 1px solid rgba(99, 102, 241, 0.15);
            border-radius: 12px;
            margin-bottom: 20px;
            padding: 16px 20px;
            position: relative;
            overflow: hidden;
        }

        .aitf-ai-welcome::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 4px;
            height: 100%;
            background: linear-gradient(to bottom, #6366f1, #d946ef);
        }

        .aitf-ai-welcome-title {
            color: #e2e8f0;
            font-size: 16px;
            font-weight: 700;
            margin-bottom: 6px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .aitf-ai-prompt-box {
            background: #111827;
            border: 1px solid rgba(168, 85, 247, 0.2);
            border-radius: 14px;
            padding: 18px;
            margin-bottom: 20px;
            box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3), 0 4px 20px rgba(0, 0, 0, 0.15);
            transition: border-color 0.3s, box-shadow 0.3s;
        }

        .aitf-ai-prompt-box:focus-within {
            border-color: rgba(168, 85, 247, 0.5);
            box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3), 0 0 15px rgba(168, 85, 247, 0.2);
        }

        .aitf-ai-prompt-box label {
            display: flex;
            align-items: center;
            gap: 6px;
            color: #a5b4fc;
            font-size: 12px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 12px;
            padding-left: 4px;
        }

        .aitf-ai-prompt-box textarea {
            background: transparent !important;
            border: none !important;
            color: #f1f5f9 !important;
            font-size: 16px !important;
            line-height: 1.6;
            min-height: 80px;
            resize: vertical;
            width: 100%;
            padding: 4px 50px 4px 6px;
            box-shadow: none !important;
            outline: none !important;
        }

        .aitf-ai-prompt-box textarea::placeholder {
            color: #4b5563;
        }

        .aitf-ai-input-wrapper {
            position: relative;
            width: 100%;
        }

        .btn-ai-send {
            position: absolute;
            right: 8px;
            bottom: 8px;
            width: 38px;
            height: 38px;
            border-radius: 50%;
            background: linear-gradient(135deg, #a855f7 0%, #7c3aed 100%);
            border: none;
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 4px 10px rgba(168, 85, 247, 0.4);
            z-index: 10;
        }

        .btn-ai-send:hover {
            transform: scale(1.08);
            box-shadow: 0 0 14px rgba(168, 85, 247, 0.6);
            background: linear-gradient(135deg, #b86bf8 0%, #8b4ef0 100%);
        }

        .btn-ai-send:active {
            transform: scale(0.95);
        }

        .btn-ai-send:disabled {
            background: #1e293b;
            color: #475569;
            box-shadow: none;
            cursor: not-allowed;
            transform: none;
        }

        .aitf-ai-model-strip {
            align-items: center;
            display: flex;
            flex-wrap: wrap;
            gap: 12px;
            margin-top: 14px;
            padding-top: 14px;
            border-top: 1px solid rgba(255, 255, 255, 0.08);
        }

        .aitf-ai-model-label {
            color: #94a3b8;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .aitf-ai-model-options {
            display: flex;
            gap: 10px;
        }

        .aitf-ai-model-option {
            background: #0d1321;
            border: 1px solid rgba(148, 163, 184, 0.15);
            border-radius: 10px;
            color: #cbd5e1;
            cursor: pointer;
            padding: 8px 16px;
            text-align: left;
            transition: all 0.2s ease;
            display: flex;
            flex-direction: column;
            gap: 2px;
            min-width: 160px;
        }

        .aitf-ai-model-option:hover {
            border-color: rgba(168, 85, 247, 0.4);
            background: rgba(255, 255, 255, 0.02);
        }

        .aitf-ai-model-option.active {
            background: rgba(168, 85, 247, 0.1);
            border-color: #a855f7;
            box-shadow: 0 0 10px rgba(168, 85, 247, 0.4);
            color: #f8fafc;
        }

        .aitf-ai-model-topline {
            align-items: center;
            display: flex;
            justify-content: space-between;
            gap: 8px;
            width: 100%;
        }

        .aitf-ai-model-name {
            font-size: 13px;
            font-weight: 700;
        }

        .aitf-ai-model-badge {
            border-radius: 4px;
            background: rgba(168, 85, 247, 0.15);
            border: 1px solid rgba(168, 85, 247, 0.3);
            color: #d8b4fe;
            font-size: 9px;
            font-weight: 800;
            padding: 1px 4px;
        }

        .aitf-ai-model-desc {
            color: #64748b;
            font-size: 11px;
            font-weight: 500;
        }

        .aitf-ai-metrics {
            color: #94a3b8;
            font-size: 13px;
        }

        /* Sleek Button Styles */
        .btn-ai-primary {
            background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #c084fc 100%);
            background-size: 200% auto;
            border: none;
            color: #ffffff !important;
            font-weight: 600;
            padding: 8px 18px;
            border-radius: 8px;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn-ai-primary:hover {
            background-position: right center;
            transform: translateY(-1px);
            box-shadow: 0 6px 20px rgba(124, 58, 237, 0.45);
        }

        .btn-ai-primary:active {
            transform: translateY(1px);
        }

        .btn-ai-primary:disabled {
            background: #1e293b !important;
            color: #475569 !important;
            box-shadow: none;
            cursor: not-allowed;
            transform: none;
        }

        .btn-ai-secondary {
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            color: #e2e8f0 !important;
            font-weight: 500;
            padding: 8px 16px;
            border-radius: 8px;
            transition: all 0.2s;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn-ai-secondary:hover {
            background: rgba(255, 255, 255, 0.1);
            border-color: rgba(255, 255, 255, 0.2);
            color: #ffffff !important;
        }

        .btn-ai-secondary:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        /* Documents Section Styles */
        .aitf-ai-documents-section {
            margin-top: 25px;
            margin-bottom: 25px;
        }

        .aitf-ai-documents-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
            flex-wrap: wrap;
            gap: 12px;
        }

        .aitf-ai-documents-header .aitf-ai-section-title {
            font-size: 16px;
            font-weight: 700;
            color: #cbd5e1;
            display: flex;
            align-items: center;
            gap: 8px;
            margin: 0;
        }

        .aitf-ai-doc-actions {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
        }

        /* AI Thinking Terminal Console Log */
        .aitf-ai-work-steps {
            background: linear-gradient(145deg, rgba(5, 7, 12, 0.96), rgba(12, 18, 31, 0.94));
            border: 1px solid rgba(99, 102, 241, 0.25);
            border-radius: 12px;
            padding: 20px;
            margin: 16px 0;
            display: none;
            box-shadow: 0 18px 45px rgba(0, 0, 0, 0.48), inset 0 1px 0 rgba(255, 255, 255, 0.04);
            position: relative;
            overflow: hidden;
        }

        .aitf-ai-work-steps::before {
            content: '';
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 12% 18%, rgba(99, 102, 241, 0.14), transparent 30%),
                radial-gradient(circle at 84% 8%, rgba(168, 85, 247, 0.10), transparent 28%);
            pointer-events: none;
        }

        .aitf-ai-work-title {
            color: #e2e8f0;
            font-weight: 700;
            font-size: 15px;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 10px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-work-title-pulse {
            align-items: center;
            background: rgba(99, 102, 241, 0.14);
            border: 1px solid rgba(165, 180, 252, 0.25);
            border-radius: 50%;
            box-shadow: 0 0 18px rgba(99, 102, 241, 0.22);
            display: inline-flex;
            height: 30px;
            justify-content: center;
            width: 30px;
            animation: aitf-soft-pulse 2.2s ease-in-out infinite;
        }

        .aitf-ai-work-title-pulse i {
            color: #a5b4fc;
        }

        .aitf-ai-work-live {
            background: rgba(16, 185, 129, 0.10);
            border: 1px solid rgba(52, 211, 153, 0.26);
            border-radius: 999px;
            color: #86efac;
            font-size: 10px;
            font-weight: 800;
            letter-spacing: 0.08em;
            margin-left: auto;
            padding: 4px 8px;
        }

        .aitf-ai-work-content {
            display: flex;
            align-items: center;
            gap: 24px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-orb-container {
            flex-shrink: 0;
            width: 104px;
            height: 104px;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .aitf-ai-orb {
            align-items: center;
            width: 58px;
            height: 58px;
            border-radius: 50%;
            background:
                radial-gradient(circle at 32% 26%, rgba(248, 250, 252, 0.92) 0%, rgba(165, 180, 252, 0.92) 14%, transparent 28%),
                radial-gradient(circle at 50% 58%, #818cf8 0%, #6366f1 46%, #4338ca 100%);
            box-shadow: 0 0 22px rgba(99, 102, 241, 0.62), 0 0 42px rgba(139, 92, 246, 0.34);
            animation: pulse-orb 2.8s infinite ease-in-out;
            color: #eff6ff;
            display: flex;
            font-size: 14px;
            font-weight: 900;
            justify-content: center;
            letter-spacing: 0.04em;
            position: relative;
            z-index: 2;
        }

        .aitf-ai-orb-ring {
            position: absolute;
            border: 1px solid rgba(165, 180, 252, 0.34);
            border-radius: 50%;
            z-index: 1;
        }

        .aitf-ai-orb-ring.ring-one {
            width: 88px;
            height: 88px;
            border-style: dashed;
            animation: rotate-ring 9s linear infinite;
        }

        .aitf-ai-orb-ring.ring-two {
            width: 102px;
            height: 72px;
            border-color: rgba(168, 85, 247, 0.28);
            transform: rotate(-24deg);
            animation: rotate-ring-tilt 12s linear infinite;
        }

        .aitf-ai-particle {
            background: #a5b4fc;
            border-radius: 50%;
            box-shadow: 0 0 10px rgba(165, 180, 252, 0.8);
            height: 4px;
            position: absolute;
            width: 4px;
            z-index: 3;
        }

        .particle-one {
            animation: aitf-particle-one 4s ease-in-out infinite;
            left: 16px;
            top: 25px;
        }

        .particle-two {
            animation: aitf-particle-two 5s ease-in-out infinite;
            right: 18px;
            top: 34px;
        }

        .particle-three {
            animation: aitf-particle-three 4.6s ease-in-out infinite;
            bottom: 24px;
            right: 34px;
        }

        @keyframes pulse-orb {

            0%,
            100% {
                transform: scale(0.95);
                filter: brightness(1) drop-shadow(0 0 10px rgba(99, 102, 241, 0.5));
            }

            50% {
                transform: scale(1.08);
                filter: brightness(1.25) drop-shadow(0 0 25px rgba(139, 92, 246, 0.8));
            }
        }

        @keyframes rotate-ring {
            100% {
                transform: rotate(360deg);
            }
        }

        @keyframes rotate-ring-tilt {
            100% {
                transform: rotate(336deg);
            }
        }

        @keyframes aitf-soft-pulse {

            0%,
            100% {
                box-shadow: 0 0 10px rgba(99, 102, 241, 0.18);
            }

            50% {
                box-shadow: 0 0 22px rgba(99, 102, 241, 0.42);
            }
        }

        @keyframes aitf-particle-one {

            0%,
            100% {
                transform: translate(0, 0);
                opacity: 0.45;
            }

            50% {
                transform: translate(14px, 20px);
                opacity: 1;
            }
        }

        @keyframes aitf-particle-two {

            0%,
            100% {
                transform: translate(0, 0);
                opacity: 0.35;
            }

            50% {
                transform: translate(-18px, 18px);
                opacity: 0.95;
            }
        }

        @keyframes aitf-particle-three {

            0%,
            100% {
                transform: translate(0, 0);
                opacity: 0.4;
            }

            50% {
                transform: translate(-10px, -18px);
                opacity: 0.9;
            }
        }

        .aitf-ai-work-log {
            flex-grow: 1;
            font-family: 'SFMono-Regular', Consolas, 'Courier New', monospace;
            background: rgba(2, 6, 23, 0.68);
            border: 1px solid rgba(148, 163, 184, 0.12);
            border-radius: 8px;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
            color: #cbd5e1;
            font-size: 12px;
            height: 126px;
            line-height: 1.55;
            overflow-y: auto;
            padding: 12px 14px;
        }

        .aitf-ai-log-line {
            align-items: baseline;
            display: flex;
            gap: 8px;
            margin: 2px 0;
            min-height: 19px;
            opacity: 0.94;
            transform: translateY(2px);
            transition: opacity 0.25s ease, transform 0.25s ease;
        }

        .aitf-ai-log-time {
            color: #64748b;
            flex: 0 0 58px;
        }

        .aitf-ai-log-level {
            border-radius: 4px;
            flex: 0 0 54px;
            font-size: 10px;
            font-weight: 800;
            letter-spacing: 0.04em;
            padding: 1px 5px;
            text-align: center;
        }

        .aitf-ai-log-line.info .aitf-ai-log-level {
            background: rgba(56, 189, 248, 0.10);
            color: #7dd3fc;
        }

        .aitf-ai-log-line.warn .aitf-ai-log-level {
            background: rgba(245, 158, 11, 0.12);
            color: #fbbf24;
        }

        .aitf-ai-log-line.success .aitf-ai-log-level {
            background: rgba(16, 185, 129, 0.12);
            color: #86efac;
        }

        .aitf-ai-log-line.audit .aitf-ai-log-level {
            background: rgba(168, 85, 247, 0.12);
            color: #d8b4fe;
        }

        .aitf-ai-log-text {
            color: #cbd5e1;
            flex: 1;
        }

        .aitf-ai-log-cursor {
            animation: aitf-cursor-blink 1s steps(1) infinite;
            color: #a5b4fc;
        }

        @keyframes aitf-cursor-blink {
            50% {
                opacity: 0;
            }
        }

        .aitf-ai-stats-panel {
            display: grid;
            gap: 10px;
            grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
            margin-top: 18px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-stat-card {
            background: rgba(15, 23, 42, 0.58);
            border: 1px solid rgba(148, 163, 184, 0.11);
            border-radius: 10px;
            min-height: 78px;
            padding: 12px;
            position: relative;
            transition: border-color 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease;
        }

        .aitf-ai-stat-card:hover {
            border-color: rgba(165, 180, 252, 0.24);
            box-shadow: 0 10px 24px rgba(0, 0, 0, 0.18);
            transform: translateY(-1px);
        }

        .aitf-ai-stat-icon {
            align-items: center;
            background: rgba(99, 102, 241, 0.12);
            border: 1px solid rgba(165, 180, 252, 0.14);
            border-radius: 8px;
            color: #a5b4fc;
            display: inline-flex;
            height: 28px;
            justify-content: center;
            margin-bottom: 8px;
            width: 28px;
        }

        .aitf-ai-stat-label {
            color: #94a3b8;
            display: block;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.03em;
            line-height: 1.25;
            text-transform: uppercase;
        }

        .aitf-ai-stat-value {
            color: #f8fafc;
            display: block;
            font-size: 20px;
            font-weight: 800;
            line-height: 1.1;
            margin-top: 5px;
        }

        .aitf-ai-steps-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(205px, 1fr));
            gap: 10px;
            margin-top: 18px;
            border-top: 1px solid rgba(255, 255, 255, 0.06);
            padding-top: 14px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-step {
            align-items: center;
            background: rgba(15, 23, 42, 0.42);
            border: 1px solid rgba(148, 163, 184, 0.10);
            border-radius: 10px;
            color: #8794a8;
            display: flex;
            gap: 10px;
            min-height: 46px;
            padding: 9px 10px;
            font-size: 13px;
            font-weight: 650;
            transition: color 0.3s ease, background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease;
        }

        .aitf-ai-step-icon {
            align-items: center;
            background: rgba(148, 163, 184, 0.07);
            border-radius: 8px;
            display: inline-flex;
            height: 28px;
            justify-content: center;
            width: 28px;
        }

        .aitf-ai-step-icon i {
            color: #475569;
            transition: color 0.3s ease, transform 0.3s ease;
        }

        .aitf-ai-step.active {
            background: rgba(99, 102, 241, 0.14);
            border-color: rgba(129, 140, 248, 0.52);
            box-shadow: 0 0 22px rgba(99, 102, 241, 0.22);
            color: #e0e7ff;
            transform: translateY(-1px);
        }

        .aitf-ai-step.active .aitf-ai-step-icon {
            background: rgba(99, 102, 241, 0.22);
            box-shadow: 0 0 18px rgba(99, 102, 241, 0.34);
        }

        .aitf-ai-step.active .aitf-ai-step-icon i {
            color: #bfdbfe;
            animation: aitf-step-pulse 1.3s ease-in-out infinite;
        }

        .aitf-ai-step.done {
            background: rgba(16, 185, 129, 0.08);
            border-color: rgba(52, 211, 153, 0.24);
            color: #34d399;
        }

        .aitf-ai-step.done .aitf-ai-step-icon {
            background: rgba(16, 185, 129, 0.13);
        }

        .aitf-ai-step.done .aitf-ai-step-icon i {
            color: #86efac;
        }

        @keyframes aitf-step-pulse {

            0%,
            100% {
                transform: scale(1);
                opacity: 0.8;
            }

            50% {
                transform: scale(1.14);
                opacity: 1;
            }
        }

        @media (max-width: 640px) {
            .aitf-ai-work-content {
                align-items: stretch;
                flex-direction: column;
                gap: 14px;
            }

            .aitf-ai-orb-container {
                align-self: center;
            }

            .aitf-ai-stats-panel,
            .aitf-ai-steps-grid {
                grid-template-columns: 1fr;
            }
        }

        .aitf-ai-status {
            border-radius: 8px;
            font-weight: 700;
            padding: 10px 14px;
            margin-bottom: 16px;
            font-size: 14px;
            border: 1px solid transparent;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .aitf-ai-status.pass {
            background: rgba(16, 185, 129, 0.1);
            color: #34d399;
            border-color: rgba(16, 185, 129, 0.2);
        }

        .aitf-ai-status.review_required {
            background: rgba(245, 158, 11, 0.1);
            color: #fbbf24;
            border-color: rgba(245, 158, 11, 0.2);
        }

        .aitf-ai-status.manual_verification_required {
            background: rgba(99, 102, 241, 0.1);
            color: #818cf8;
            border-color: rgba(99, 102, 241, 0.2);
        }

        .aitf-ai-status.failed {
            background: rgba(239, 68, 68, 0.1);
            color: #f87171;
            border-color: rgba(239, 68, 68, 0.2);
        }

        /* Sleek Document Table wrap */
        .aitf-ai-doc-table-wrap {
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 12px;
            background: rgba(15, 23, 42, 0.4);
            max-height: 380px;
            overflow-y: auto;
        }

        /* Custom Scrollbars */
        .aitf-ai-doc-table-wrap::-webkit-scrollbar {
            width: 6px;
        }

        .aitf-ai-doc-table-wrap::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.2);
        }

        .aitf-ai-doc-table-wrap::-webkit-scrollbar-thumb {
            background: rgba(99, 102, 241, 0.3);
            border-radius: 4px;
        }

        .aitf-ai-doc-table-wrap::-webkit-scrollbar-thumb:hover {
            background: rgba(99, 102, 241, 0.5);
        }

        .aitf-ai-doc-table {
            width: 100%;
            margin-bottom: 0;
            border-collapse: collapse;
        }

        .aitf-ai-doc-table th {
            background: rgba(15, 23, 42, 0.8) !important;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
            color: #94a3b8 !important;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            padding: 12px 16px !important;
            position: sticky;
            top: 0;
            z-index: 10;
        }

        .aitf-ai-doc-table td {
            border-bottom: 1px solid rgba(255, 255, 255, 0.05) !important;
            padding: 14px 16px !important;
            vertical-align: middle !important;
            color: #cbd5e1;
        }

        .aitf-ai-doc-table tbody tr {
            transition: background-color 0.2s;
        }

        .aitf-ai-doc-table tbody tr:hover {
            background-color: rgba(99, 102, 241, 0.04);
        }

        .aitf-ai-doc-name {
            color: #f1f5f9;
            font-weight: 600;
            font-size: 14px;
        }

        .aitf-ai-doc-link {
            color: #f1f5f9;
            display: inline-flex;
            align-items: center;
            text-decoration: none;
        }

        .aitf-ai-doc-link:hover,
        .aitf-ai-doc-link:focus {
            color: #ffffff;
            text-decoration: underline;
        }

        .aitf-ai-doc-meta {
            color: #94a3b8;
            font-size: 13px;
        }

        .doc-meta-separator {
            color: #475569;
            margin: 0 4px;
        }

        .aitf-ai-scan-pill {
            border-radius: 20px;
            display: inline-flex;
            align-items: center;
            gap: 5px;
            font-size: 11px;
            font-weight: 600;
            padding: 4px 10px;
            text-transform: uppercase;
        }

        .aitf-ai-scan-pill.scanned {
            background: rgba(16, 185, 129, 0.12);
            color: #34d399;
            border: 1px solid rgba(16, 185, 129, 0.3);
        }

        .aitf-ai-scan-pill.not-scanned {
            background: rgba(239, 68, 68, 0.12);
            color: #f87171;
            border: 1px solid rgba(239, 68, 68, 0.3);
        }

        .aitf-ai-doc-actions {
            display: flex;
            gap: 6px;
        }

        .aitf-ai-doc-actions .btn {
            border-radius: 6px;
            font-size: 11px;
            font-weight: 600;
            padding: 4px 8px;
            transition: all 0.2s;
        }

        .aitf-ai-doc-actions .btn-default {
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            color: #cbd5e1;
        }

        .aitf-ai-doc-actions .btn-default:hover {
            background: rgba(255, 255, 255, 0.15);
            color: #fff;
        }

        .aitf-ai-doc-actions .btn-primary {
            background: rgba(99, 102, 241, 0.2);
            border: 1px solid rgba(99, 102, 241, 0.4);
            color: #a5b4fc;
        }

        .aitf-ai-doc-actions .btn-primary:hover {
            background: rgba(99, 102, 241, 0.4);
            color: #fff;
        }

        .aitf-ai-empty {
            background: rgba(15, 23, 42, 0.2);
            border: 1px dashed rgba(99, 102, 241, 0.2);
            border-radius: 12px;
            color: #64748b;
            padding: 24px;
            text-align: center;
            font-size: 14px;
        }

        /* FIXED AI Response Section Styles */
        .aitf-ai-response-section {
            background: #ffffff;
            color: #1e293b;
            border-radius: 12px;
            margin-top: 25px;
            padding: 24px;
            border: 1px solid #e2e8f0;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
        }

        .docora-review-header {
            border-bottom: 2px solid #f1f5f9;
            padding-bottom: 18px;
            margin-bottom: 20px;
        }

        .docora-review-title {
            font-size: 20px;
            font-weight: 800;
            color: #0f172a;
            margin-bottom: 12px;
            letter-spacing: -0.02em;
        }

        .docora-review-meta-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
            gap: 12px;
        }

        .docora-meta-item {
            display: flex;
            flex-direction: column;
            gap: 4px;
        }

        .docora-meta-label {
            font-size: 11px;
            font-weight: 700;
            text-transform: uppercase;
            color: #64748b;
            letter-spacing: 0.05em;
        }

        .docora-meta-value {
            font-size: 14px;
            font-weight: 600;
            color: #334155;
        }

        .docora-badge {
            display: inline-block;
            width: fit-content;
            padding: 4px 10px;
            border-radius: 6px;
            font-size: 11px;
            font-weight: 700;
            text-transform: uppercase;
        }

        /* Status colors */
        .docora-badge.status-pass {
            background: #d1fae5;
            color: #065f46;
        }

        .docora-badge.status-review_required {
            background: #fef3c7;
            color: #92400e;
        }

        .docora-badge.status-manual_verification_required {
            background: #e0e7ff;
            color: #3730a3;
        }

        .docora-badge.status-failed {
            background: #fee2e2;
            color: #991b1b;
        }

        /* Risk colors */
        .docora-badge.risk-low {
            background: #d1fae5;
            color: #065f46;
        }

        .docora-badge.risk-medium {
            background: #fef3c7;
            color: #92400e;
        }

        .docora-badge.risk-high {
            background: #fee2e2;
            color: #991b1b;
        }

        .docora-response-body-wrapper {
            padding-top: 8px;
        }

        .docora-response-heading {
            font-size: 15px;
            font-weight: 800;
            color: #64748b;
            text-transform: uppercase;
            letter-spacing: 0.08em;
            margin-top: 0;
            margin-bottom: 16px;
            border-bottom: 1px solid #f1f5f9;
            padding-bottom: 8px;
        }

        .docora-response-text {
            font-size: 16px;
            line-height: 1.65;
            color: #1e293b;
        }

        .docora-response-para {
            margin-bottom: 18px;
            color: #334155;
        }

        .docora-response-para strong {
            color: #0f172a;
        }

        .docora-response-para em {
            font-style: italic;
            color: #475569;
        }

        .docora-empty-msg {
            color: #94a3b8;
            font-size: 15px;
            font-style: italic;
        }

        .docora-loading-msg {
            color: #64748b;
            font-size: 15px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .go-ai-conversation {
            display: flex;
            flex-direction: column;
            gap: 14px;
        }

        .go-ai-chat-message {
            border: 1px solid #e2e8f0;
            border-radius: 10px;
            max-width: 94%;
            padding: 14px 16px;
        }

        .go-ai-chat-message.assistant {
            align-self: flex-start;
            background: #f8fafc;
        }

        .go-ai-chat-message.user {
            align-self: flex-end;
            background: #eef2ff;
            border-color: #c7d2fe;
        }

        .go-ai-chat-speaker {
            color: #475569;
            display: block;
            font-size: 11px;
            font-weight: 800;
            letter-spacing: 0.06em;
            margin-bottom: 8px;
            text-transform: uppercase;
        }

        .go-ai-chat-message.user .docora-response-para {
            margin-bottom: 0;
        }

        .go-ai-reply-box {
            border-top: 1px solid #f1f5f9;
            margin-top: 18px;
            padding-top: 16px;
        }

        .go-ai-reply-label {
            color: #475569;
            display: block;
            font-size: 12px;
            font-weight: 800;
            letter-spacing: 0.06em;
            margin-bottom: 8px;
            text-transform: uppercase;
        }

        .go-ai-reply-input-row {
            align-items: flex-end;
            display: flex;
            gap: 10px;
        }

        #aitfAiReplyPrompt {
            min-height: 54px;
            resize: vertical;
        }

        .go-ai-reply-send {
            border-radius: 8px;
            flex: 0 0 auto;
            min-height: 54px;
            padding: 10px 16px;
        }

        @media (max-width: 767px) {
            .go-ai-reply-input-row {
                align-items: stretch;
                flex-direction: column;
            }

            .go-ai-reply-send {
                width: 100%;
            }
        }

        .modal-footer {
            background: #070a10;
            border-top: 1px solid rgba(99, 102, 241, 0.15);
            padding: 14px 24px;
        }

        @media (max-width: 767px) {
            .docora-review-meta-grid {
                grid-template-columns: 1fr 1fr;
            }
        }

        .aitf_service_date {
            background: #0b4f8a;
            color: #ffffff;
            font-size: 13px;
            font-weight: 700;
            letter-spacing: 0;
            line-height: 1.4;
            padding: 8px 10px;
            text-shadow: 0 1px 1px rgba(0, 0, 0, 0.25);
        }

        /* =====================================================================
           TOP CLIENT INFO SECTION — CLEAN FONTS & CRISP WHITE CONTRAST
           ===================================================================== */
        .top_qms_page,
        .background_lightblue {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
            background: #ffffff !important;
            border: 1px solid #e2e8f0 !important;
            border-radius: 12px !important;
            box-shadow: 0 4px 16px rgba(15, 23, 42, 0.04) !important;
            margin-bottom: 15px !important;
            overflow: hidden !important;
        }

        /* Top Header & Headings matching masterCreator gradient headers */
        .qms_customer_name {
            background: linear-gradient(135deg, #0d4d8b 0%, #1e40af 100%) !important;
            color: #ffffff !important;
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
            font-weight: 700 !important;
            font-size: 15px !important;
            letter-spacing: 0.3px !important;
            border-radius: 12px 12px 0 0 !important;
            box-shadow: 0 2px 8px rgba(13, 77, 139, 0.15) !important;
            text-transform: uppercase !important;
        }

        .qms_customer_name.canceled-client-header {
            background: linear-gradient(135deg, #991b1b 0%, #dc2626 100%) !important;
        }

        .qms_customer_name.supplier-account-header {
            background: linear-gradient(135deg, #5b21b6 0%, #7c3aed 100%) !important;
        }

        /* Top Client Header ONLY (Not ISO headers, Not services) */
        .top_qms_page > .row:first-child > .qms_customer_name {
            min-height: 48px !important;
            height: auto !important;
            padding: 8px 16px !important;
            display: flex !important;
            align-items: center !important;
        }

        /* Field Labels */
        .top_qms_page span[style*="color: black"],
        .top_qms_page span[style*="color:black"] {
            color: #0d4d8b !important;
            font-size: 11.5px !important;
            font-weight: 700 !important;
            letter-spacing: 0.3px !important;
            display: inline-block;
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
        }

        /* Field Values */
        .top_qms_page span[style*="color: gray"],
        .top_qms_page span[style*="color:gray"] {
            color: #0f172a !important;
            font-size: 12.5px !important;
            font-weight: 500 !important;
            line-height: 1.45 !important;
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
        }

        /* Add Notes Textarea */
        .top_qms_page textarea.notebox,
        #add-notes {
            background: #f8fafc !important;
            border: 1px solid #cbd5e1 !important;
            border-radius: 8px !important;
            color: #0f172a !important;
            font-size: 12.5px !important;
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
            line-height: 1.5 !important;
            padding: 8px 12px !important;
            box-sizing: border-box !important;
            transition: all 0.2s ease !important;
            width: 100% !important;
        }

        .top_qms_page textarea.notebox:focus,
        #add-notes:focus {
            background: #ffffff !important;
            border-color: #0d4d8b !important;
            box-shadow: 0 0 0 3px rgba(13, 77, 139, 0.12) !important;
            outline: none !important;
        }

        .top_qms_page hr {
            border-color: #e2e8f0 !important;
            margin: 0 !important;
        }

        /* =====================================================================
           SECTION CARDS, BOXES & BUTTONS (MATCHING MASTERCREATOR)
           ===================================================================== */
        .servicebox {
            background: #ffffff !important;
            border: 1px solid #e2e8f0 !important;
            border-radius: 12px !important;
            box-shadow: 0 4px 16px rgba(15, 23, 42, 0.04) !important;
            overflow: hidden !important;
            margin-bottom: 16px !important;
        }

        .servicebox-data {
            background: #ffffff !important;
        }

        .service_title,
        .cr-service-row,
        .ca-service-row,
        .sai-service-row,
        .saii-service-row,
        .rc-service-row,
        .sp-service-row,
        .ta-service-row,
        .payment-row,
        .service-row,
        .servicebox .service_title,
        .servicebox-bunch .service_title,
        .qms_customer_name.service_title {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
            font-weight: 700 !important;
            cursor: pointer !important;
            user-select: none !important;
            -webkit-user-select: none !important;
            -moz-user-select: none !important;
            -ms-user-select: none !important;
        }

        .service_title *,
        .cr-service-row *,
        .ca-service-row *,
        .sai-service-row *,
        .saii-service-row *,
        .rc-service-row *,
        .sp-service-row *,
        .ta-service-row *,
        .payment-row *,
        .service-row *,
        .servicebox .service_title *,
        .servicebox-bunch .service_title *,
        .qms_customer_name.service_title * {
            cursor: pointer !important;
        }

        .cr-service-row:hover,
        .ca-service-row:hover,
        .sai-service-row:hover,
        .saii-service-row:hover,
        .rc-service-row:hover,
        .sp-service-row:hover,
        .ta-service-row:hover,
        .payment-row:hover,
        .service_title:hover {
            filter: brightness(1.12) !important;
            transition: filter 0.15s ease !important;
        }

        .service_title a.deleteServiceCR:hover i,
        .service_title a.deleteServiceCA:hover i,
        .service_title a[class*="deleteService"]:hover i {
            color: #ef4444 !important;
        }

        .payment-header-toggle-row,
        .service_title.payment-title,
        .payment-title {
            background: linear-gradient(135deg, #1e293b 0%, #334155 100%) !important;
            color: #ffffff !important;
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
            font-weight: 700 !important;
            border-radius: 6px 6px 0 0 !important;
            box-shadow: 0 2px 6px rgba(15, 23, 42, 0.15) !important;
            margin-left: 0 !important;
            margin-right: 0 !important;
            border: none !important;
        }

        .payment-title .savePayment i {
            transition: all 0.2s ease !important;
        }
        .payment-title .savePayment:hover i {
            transform: scale(1.15) !important;
            text-shadow: 0 0 10px rgba(255, 255, 255, 0.8) !important;
        }

        /* ========================================================
           PAYMENT SYSTEM - CLEAN MINIMAL WHITE & SLATE THEME
           ======================================================== */
        .payment-desc {
            background: #ffffff !important;
            border: 1px solid #e2e8f0 !important;
            border-top: none !important;
            border-radius: 0 0 8px 8px !important;
            padding: 10px 14px 14px 14px !important;
            box-shadow: 0 4px 12px rgba(15, 23, 42, 0.04) !important;
        }

        /* Payment System Section Headers (Invoice, Payments, Payment Summary) */
        .payment-desc .qms_complete_btn {
            background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%) !important;
            border: 1px solid #cbd5e1 !important;
            border-radius: 6px !important;
            color: #1e293b !important;
            box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04) !important;
            font-weight: 700 !important;
            letter-spacing: 0.4px !important;
            transition: all 0.2s ease !important;
        }

        .payment-desc .qms_complete_btn:hover {
            background: linear-gradient(135deg, #f1f5f9 0%, #e2e8f0 100%) !important;
            box-shadow: 0 2px 5px rgba(0, 0, 0, 0.08) !important;
            color: #0f172a !important;
        }

        /* Table Headers in Payment System */
        .payment-desc .service_details thead th,
        .payment-desc .service_details thead th small,
        #invoice_service_details thead th,
        #invoice_service_details thead th small,
        #payment_summary_table thead th,
        #payment_summary_table thead th small {
            background: #f8fafc !important;
            color: #334155 !important;
            border-bottom: 2px solid #cbd5e1 !important;
            border-color: #e2e8f0 !important;
            font-weight: 700 !important;
        }

        /* Input Controls in Payment System */
        .payment-desc .table-edit-control input,
        .payment-desc .table-edit-control select {
            color: #0f172a !important;
            font-size: 12px !important;
            font-weight: 500 !important;
        }

        .payment-desc .table-edit-control input:focus,
        .payment-desc .table-edit-control select:focus,
        .payment-desc input.form-control:focus {
            background-color: #ffffff !important;
            border-color: #2563eb !important;
            box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.15) !important;
            outline: none !important;
        }

        /* Row Hover in Payment System */
        .payment-desc .service_details tbody tr:hover td {
            background-color: #f8fafc !important;
        }

        /* Add Row (+) Button in Payments Table */
        .payment-desc .cbAddLink,
        #service_details .cbAddLink {
            background: linear-gradient(135deg, #1e293b, #334155) !important;
            border: 1px solid #1e293b !important;
            color: #ffffff !important;
            box-shadow: 0 1px 3px rgba(30, 41, 59, 0.25) !important;
            border-radius: 4px !important;
            padding: 1px 6px !important;
        }
        .payment-desc .cbAddLink:hover,
        #service_details .cbAddLink:hover {
            background: linear-gradient(135deg, #2563eb, #1d4ed8) !important;
            border-color: #1e40af !important;
            color: #ffffff !important;
            transform: scale(1.08);
        }

        /* Invoice Edit Icon */
        .payment-desc .editFinalInvoice i.fa-pencil-square {
            color: #2563eb !important;
            transition: transform 0.15s ease, color 0.15s ease;
        }
        .payment-desc .editFinalInvoice:hover i.fa-pencil-square {
            color: #1d4ed8 !important;
            transform: scale(1.22);
        }

        /* Invoice Comments Input/Textarea Styling */
        .invoiceRemark {
            width: 100% !important;
            height: 38px !important;
            min-height: 36px !important;
            max-height: 48px !important;
            line-height: 1.25 !important;
            border: 1px solid #cbd5e1 !important;
            border-radius: 4px !important;
            padding: 3px 6px !important;
            font-size: 11px !important;
            color: #1e293b !important;
            background: #ffffff !important;
            resize: none !important;
            transition: all 0.2s ease !important;
            box-sizing: border-box !important;
            display: block !important;
            font-family: inherit !important;
        }
        .invoiceRemark:hover {
            background: #ffffff !important;
            border-color: #94a3b8 !important;
        }
        .invoiceRemark:focus {
            background: #ffffff !important;
            border-color: #2563eb !important;
            outline: none !important;
            box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.15) !important;
        }
        html.theme-dark .invoiceRemark {
            color: #e2e8f0 !important;
            background: #1e293b !important;
            border-color: #475569 !important;
        }
        html.theme-dark .invoiceRemark:hover {
            background: #1e293b !important;
            border-color: #64748b !important;
        }
        html.theme-dark .invoiceRemark:focus {
