                $saiSuspendDate = '';
                $prevServiceQuery = "SELECT service_id FROM service WHERE customer_id = :id AND service_id < :currId AND (is_deleted = 'NO' OR is_deleted IS NULL) ORDER BY service_id DESC LIMIT 1";
