                        aitfShowReviewResponse(response);
                    },
                    error: function (xhr) {
                        var message = xhr.responseJSON && xhr.responseJSON.message ? xhr.responseJSON.message : 'Unable to load saved AI review.';
                        aitfSetAiStatus(message, 'failed');
