                console.log('Control Format 1 Modal Shown - Fetching certificates for:', customerId);
                console.log('Container exists:', $('#certificateNumbersContainer').length);

                $.ajax({
                    url: "getCACertificateNumber.php",
                    type: "GET",
                    dataType: "json",
