        // Add Invoice Header Button Click Handler
        $(document).on('click', '.btnAddInvoiceHeader', function (e) {
            if (e && e.stopPropagation) e.stopPropagation();
            if (e && e.preventDefault) e.preventDefault();

            var $pDesc = $('.payment-desc');
            if ($pDesc.is(':hidden')) {
                $pDesc.slideDown(200);
                $('.btnAddInvoiceHeader').css('display', 'inline-flex');
                $('.payment-toggle-chevron').css('transform', 'rotate(180deg)');
            }

            var availableServices = ['CA', 'SA-I', 'SA-II', 'RC', 'SP', 'Contract Review', 'PTR', 'Transition Audit', 'Generic Training', 'Other'];
            var currentActiveServices = [];
            $('.service-payment-block').each(function () {
                var s = $(this).attr('data-service');
                if (s) currentActiveServices.push(s.toUpperCase());
            });

            var nextService = 'SA-I';
            for (var i = 0; i < availableServices.length; i++) {
                if (availableServices[i] !== 'Other' && currentActiveServices.indexOf(availableServices[i].toUpperCase()) === -1) {
                    nextService = availableServices[i];
                    break;
                }
            }

            var blockIndex = $('.service-payment-block').length;
            var customerId = <?php echo json_encode((string)($_GET["customerid"] ?? "")); ?>;
            var customerAddress = <?php echo json_encode((string)($clientInfo["address"] ?? "")); ?>;

            var newBlockHtml = renderServiceBlockTemplate(nextService, blockIndex, customerId, customerAddress, availableServices);

            $('#service_blocks_container').append(newBlockHtml);
            $('#activeServicesCountBadge').text($('.service-payment-block').length + ' Active');

            var $newBlock = $('.service-payment-block').last();
            $('html, body').animate({
                scrollTop: $newBlock.offset().top - 80
            }, 400);

            recalculatePaymentSystem();
        });

        // Helper function to apply service change to block, payments, and invoices
        function applyServiceBlockTypeChange($block, newSvc) {
            $block.attr('data-service', newSvc);
            $block.find('.serviceBlockBadge').text(newSvc);
            $block.find('.col-service-label').text(newSvc);
            $block.find('.finalInvoiceBtn').attr('data-service', newSvc).attr('title', 'Create Final Invoice Against ' + newSvc);
            $block.find('.cbAddLink').attr('data-service', newSvc);
            $block.find('.openDiscountModalBtn').attr('data-service', newSvc);
            $block.find('.totalInvoiceTableSum').attr('title', 'Total Invoicing Amount for ' + newSvc);
            $block.find('.totalPaymentReceivedSum').attr('title', 'Total Payment Received for ' + newSvc);
            $block.find('.totalPaymentTdsSum').attr('title', 'Total TDS Amount for ' + newSvc);
            $block.find('.col-service-comment-label').text(newSvc);
            $block.find('.serviceBlockComment').attr('data-service', newSvc).attr('placeholder', 'Notes (if any)...');

            var $prevDivider = $block.prev('.service-block-divider');
            if ($prevDivider.length) {
                $prevDivider.find('.divider-service-label').text(newSvc);
            }

            // Update all payment rows in this block
            $block.find('.service-details-table tbody tr.cb_subsection').each(function () {
                $(this).find('.serviceTypeName').val(newSvc);
                var payId = $(this).find('.row-id').val();
                if (payId && payId !== '' && payId !== '0') {
                    $.ajax({
                        url: "addPayment.php",
                        type: "POST",
                        data: {
                            action: "updatePaymentServiceType",
                            payment_id: payId,
                            service_type: newSvc
                        },
                        dataType: "json"
                    });
                }
            });

            // Update all invoices in this block
            $block.find('.invoice-service-details-table tbody tr.cb_subsection').each(function () {
                var invId = $(this).find('.viewFinalInvoice').attr('data-id');
                if (invId && invId !== '' && invId !== '0') {
                    $.ajax({
                        url: "addPayment.php",
                        type: "POST",
                        data: {
                            action: "updateInvoiceServiceType",
                            invoice_id: invId,
                            service_type: newSvc
                        },
                        dataType: "json"
                    });
                }
            });

            recalculatePaymentSystem();
            triggerPaymentAutoSave(true);
        }

        // Helper to check blocked/disallowed service terms
        function checkBlockedServiceWord(name) {
            if (!name) return false;
            var lower = name.toLowerCase().trim();
            var blocked = ['consultency', 'consultancy', 'consulting', 'consultant', 'consult', 'help', 'support', 'internal audit', 'documentation'];
            for (var i = 0; i < blocked.length; i++) {
                if (lower.indexOf(blocked[i]) !== -1) {
                    return true;
                }
            }
            return false;
        }

        // Prompt custom service name via SweetAlert2 Modal Popup
        function promptCustomService($block, prevSvc) {
            var $select = $block.find('.serviceBlockTypeSelect');
            if (typeof Swal !== 'undefined' && Swal.fire) {
                Swal.fire({
                    title: '<span style="font-weight: 700; font-size: 17px; color: #0f172a;">Enter Custom Service Name</span>',
                    input: 'text',
                    inputPlaceholder: 'Enter service name...',
                    showCancelButton: true,
                    confirmButtonText: '<i class="fa fa-check" style="margin-right: 4px;"></i> Apply Service',
                    cancelButtonText: 'Cancel',
                    confirmButtonColor: '#2563eb',
                    cancelButtonColor: '#64748b',
                    width: 380,
                    padding: '1.25rem',
                    inputAttributes: {
                        autocapitalize: 'characters',
                        style: 'text-transform: uppercase; font-weight: 700; font-size: 13px; text-align: center;'
                    },
                    inputValidator: function(value) {
                        var val = (value || '').trim();
                        if (!val) {
                            return 'Please enter a service name!';
                        }
                        if (checkBlockedServiceWord(val)) {
                            return 'Such type of service is not allow';
                        }
                    }
                }).then(function(result) {
                    if (result.isConfirmed && result.value) {
                        var enteredVal = result.value.trim();
                        var newSvc = enteredVal;
                        var exists = false;
                        $select.find('option').each(function () {
                            if ($(this).val().toLowerCase() === newSvc.toLowerCase()) {
                                exists = true;
                                $(this).prop('selected', true);
                                newSvc = $(this).val();
                            }
                        });

                        if (!exists) {
                            var $otherOpt = $select.find('option[value="Other"], option[value="OTHER"]');
                            if ($otherOpt.length) {
                                $('<option value="' + newSvc + '" selected>' + newSvc + '</option>').insertBefore($otherOpt);
                            } else {
                                $select.append('<option value="' + newSvc + '" selected>' + newSvc + '</option>');
                            }
                        }

                        $select.val(newSvc);
                        applyServiceBlockTypeChange($block, newSvc);
                    } else {
                        $select.val(prevSvc);
                    }
                });
            } else {
                var enteredVal = prompt("Enter custom service name:");
                if (enteredVal && enteredVal.trim()) {
                    var trimmed = enteredVal.trim();
                    if (checkBlockedServiceWord(trimmed)) {
                        alert("Such type of service is not allow");
                        $select.val(prevSvc);
                        return;
                    }
                    var newSvc = trimmed;
                    var exists = false;
                    $select.find('option').each(function () {
                        if ($(this).val().toLowerCase() === newSvc.toLowerCase()) {
                            exists = true;
                            $(this).prop('selected', true);
                            newSvc = $(this).val();
                        }
                    });
                    if (!exists) {
                        var $otherOpt = $select.find('option[value="Other"], option[value="OTHER"]');
                        if ($otherOpt.length) {
                            $('<option value="' + newSvc + '" selected>' + newSvc + '</option>').insertBefore($otherOpt);
                        } else {
                            $select.append('<option value="' + newSvc + '" selected>' + newSvc + '</option>');
                        }
                    }
                    $select.val(newSvc);
                    applyServiceBlockTypeChange($block, newSvc);
                } else {
                    $select.val(prevSvc);
                }
            }
        }

        // Service Block Type Select Change
        $(document).on('change', '.serviceBlockTypeSelect', function () {
            var newSvc = $(this).val();
            var $select = $(this);
            var $block = $(this).closest('.service-payment-block');
            var prevSvc = $block.attr('data-service') || 'CA';

            if (newSvc === 'Other' || newSvc === 'OTHER' || (newSvc && newSvc.toLowerCase() === 'other')) {
                // Open stylish popup prompt for custom service name
                promptCustomService($block, prevSvc);
                return;
            }

            applyServiceBlockTypeChange($block, newSvc);
        });

        // Remove Service Block Button Click Handler
        $(document).on('click', '.removeServiceBlockBtn', function () {
            var $block = $(this).closest('.service-payment-block');
            var hasSavedInvoice = false;
            $block.find('.invoiceRemark').each(function () {
                var id = $(this).attr('data-invoice-id');
                if (id && id !== '0') hasSavedInvoice = true;
            });
            $block.find('.viewFinalInvoice').each(function () {
                var id = $(this).attr('data-id');
                if (id && id !== '0') hasSavedInvoice = true;
            });
            var hasSavedPayment = false;
            $block.find('.row-id').each(function () {
                var pid = $(this).val();
                if (pid && pid !== '' && pid !== '0') hasSavedPayment = true;
            });

            if (hasSavedInvoice || hasSavedPayment) {
                alert("This service block contains saved invoice or payment records and cannot be removed directly. Please delete or reassign the records first.");
                return;
            }

            if (confirm("Are you sure you want to remove this service header section?")) {
                var $prevDivider = $block.prev('.service-block-divider');
                if ($prevDivider.length) {
                    $prevDivider.remove();
                }
                $block.remove();
                $('#activeServicesCountBadge').text($('.service-payment-block').length + ' Active');
                recalculatePaymentSystem();
            }
        });

        // Live calculation on amount changes
        $(document).on('input keyup change', '.servicePaymentReceived, .serviceTdsAmount', function () {
            var $row = $(this).closest('tr');
            var received = parseFloat($row.find('.servicePaymentReceived').val()) || 0;
            var tds = parseFloat($row.find('.serviceTdsAmount').val()) || 0;

            if (received < 0) {
                alert('Payment received cannot be negative.');
                $row.find('.servicePaymentReceived').val(0);
                received = 0;
            }
            if (tds < 0) {
                alert('TDS amount cannot be negative.');
                $row.find('.serviceTdsAmount').val(0);
                tds = 0;
            }

            var discount = parseFloat($row.find('.serviceDiscountAmount').val()) || 0;
            $row.find('.serviceAmountDecided').val((received + tds + discount).toFixed(2));
            $row.find('.serviceBalance').val('0.00');

            recalculatePaymentSystem();
        });

        // Remove new unsaved payment row
        $(document).on('click', '.removeNewPaymentRow', function () {
            $(this).closest('tr').remove();
            recalculatePaymentSystem();
        });

        // Run initial calculation
        setTimeout(function () {
            recalculatePaymentSystem();
        }, 200);

        // Discount (Short Paid) Modal Handlers
        $(document).on('click', '.openDiscountModalBtn', function (e) {
            e.preventDefault();
            var calc = (typeof recalculatePaymentSystem === 'function') ? recalculatePaymentSystem() : null;
            var rem = (calc && calc.remainingBalance > 0) ? calc.remainingBalance : 0;
            $("#discountModalRemainingBalance").text(rem.toFixed(2));
            $("#modalDiscountAmount").val(rem > 0 ? rem.toFixed(2) : '');

            var $firstOpt = $("#modalDiscountInvoice option:selected");
            if (!$firstOpt.length) {
                $firstOpt = $("#modalDiscountInvoice option:first");
            }
            if ($firstOpt.length) {
                var invId = $firstOpt.attr('data-id') || '';
                $("#modalDiscountInvoiceId").val(invId);
            }
            $("#discountModal").modal('show');
        });

        $(document).on('change', '#modalDiscountInvoice', function () {
            var $opt = $(this).find('option:selected');
            var invId = $opt.attr('data-id') || '';
            $("#modalDiscountInvoiceId").val(invId);
        });

        $(document).on('click', '#btnAutoFillFullBalance', function () {
            var rem = parseFloat($("#discountModalRemainingBalance").text()) || 0;
            if (rem <= 0) {
                alert("Remaining balance is already ₹0.00 or settled.");
                return;
            }
            $("#modalDiscountAmount").val(rem.toFixed(2));
        });

        $(document).on('click', '#btnSaveDiscountSettlement', function () {
            var discountAmt = parseFloat($("#modalDiscountAmount").val()) || 0;
            if (discountAmt <= 0) {
                alert("Please enter a valid discount amount greater than 0.");
                $("#modalDiscountAmount").focus();
                return;
            }

            var selectedInvNo = $("#modalDiscountInvoice").val() || "";
            var selectedInvId = $("#modalDiscountInvoiceId").val() || ($("#modalDiscountInvoice").find('option:selected').attr('data-id') || "");
            var discDate = $("#modalDiscountDate").val() || '<?php echo date('d.m.Y'); ?>';
            var discRemarks = $("#modalDiscountRemarks").val() || "Short Paid";
            var customerID = '<?php echo $_GET['customerid'] ?? ''; ?>';

            if (!selectedInvNo) {
                alert("Please select an invoice number.");
                $("#modalDiscountInvoice").focus();
                return;
            }

            var $btn = $(this);
            $btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i> Saving...');

            $.ajax({
                url: 'addPayment.php',
                type: 'POST',
                data: {
                    action: 'saveDiscount',
                    customer_id: customerID,
                    discount_amount: discountAmt,
                    invoice_no: selectedInvNo,
                    invoice_id: selectedInvId,
                    discount_date: discDate,
                    remarks: discRemarks
                },
                dataType: 'json',
                success: function (res) {
                    $btn.prop('disabled', false).html('<i class="fa fa-check-circle"></i> Save &amp; Settle Discount');
                    if (res && res.success) {
                        location.reload(true);
                    } else {
                        alert("Error: " + ((res && res.message) ? res.message : "Failed to save discount"));
                    }
                },
                error: function (xhr, status, err) {
                    $btn.prop('disabled', false).html('<i class="fa fa-check-circle"></i> Save &amp; Settle Discount');
                    alert("Network/Server error while saving discount: " + status);
                }
            });
        });

        $(document).on('change', '.invoiceServiceTypeSelect', function () {
            var $sel = $(this);
