        $(document).on('blur change', '.invoiceRemark', function () {
            clearTimeout(invoiceRemarkTimer);
            autoSaveInvoiceRemark($(this));
        });

        // Payment System Auto-save
        var paymentAutoSaveTimer = null;
        var isPaymentSaving = false;
        var paymentSavePending = false;

        function triggerPaymentAutoSave(immediate) {
            if (paymentAutoSaveTimer) {
                clearTimeout(paymentAutoSaveTimer);
                paymentAutoSaveTimer = null;
            }
            if (immediate) {
                executePaymentAutoSave();
            } else {
                showAutoSaveIndicator('saving', 'Saving...');
                paymentAutoSaveTimer = setTimeout(function () {
                    executePaymentAutoSave();
                }, 500);
            }
        }

        function executePaymentAutoSave() {
            if (isPaymentSaving) {
                paymentSavePending = true;
                return;
            }

            var paymentID = $('#paymentAutoSaveStatus').attr('data-row-id') || $('.savePayment').attr('data-row-id') || '';
            var customerID = '<?php echo $_GET['customerid'] ?? '' ?>';

            var $matchedRows = [];
            var serviceTypeArray = [];
            var serviceAmountArray = [];
            var paymentReceivedArray = [];
            var tdsAmountArray = [];
            var discountAmountArray = [];
            var depositDateArray = [];
            var serviceChequeArray = [];
            var reconciliationArray = [];
            var rowidArray = [];

            $(".service-details-table tbody tr.cb_subsection, #service_details tbody tr.cb_subsection").each(function () {
                var $row = $(this);
                var sType = ($row.find(".serviceTypeName").val() || "").trim();
                if (sType === "") {
                    sType = $row.closest('.service-payment-block').attr('data-service') || "Payment";
                }
                var received = $row.find(".servicePaymentReceived").val();
                var tds = $row.find(".serviceTdsAmount").val();
                var discount = $row.find(".serviceDiscountAmount").val();
                var dateVal = $row.find(".paymentDepositDate").val();
                var chkVal = $row.find(".serviceChequeDetails").val();
                var recVal = $row.find(".serviceReconciliation").val();
                var rId = $row.find(".row-id").val();

                var hasData = (received !== "" && received !== null && received !== undefined) ||
                              (tds !== "" && tds !== null && tds !== undefined) ||
                              (discount !== "" && discount !== null && discount !== undefined) ||
                              (dateVal !== "" && dateVal !== null && dateVal !== undefined) ||
                              (chkVal !== "" && chkVal !== null && chkVal !== undefined) ||
                              (recVal && (recVal.toLowerCase() === "verified" || recVal.toLowerCase() === "yes" || recVal === "1")) ||
                              (rId !== "" && rId !== null && rId !== undefined && rId !== "0");

                if (!hasData) {
                    return;
                }

                var rcvNum = parseFloat(received) || 0;
                var tdsNum = parseFloat(tds) || 0;
                var discNum = parseFloat(discount) || 0;

                $matchedRows.push($row);
                serviceTypeArray.push(sType);
                serviceAmountArray.push((rcvNum + tdsNum + discNum).toFixed(2));
                paymentReceivedArray.push(received || "0");
                tdsAmountArray.push(tds || "0");
                discountAmountArray.push(discount || "0");
                depositDateArray.push(dateVal || "");
                serviceChequeArray.push(chkVal || "");
                reconciliationArray.push(recVal || "");
                rowidArray.push(rId || "");
            });

            if ($matchedRows.length === 0) {
                showAutoSaveIndicator('saved');
                return;
            }

            isPaymentSaving = true;
            showAutoSaveIndicator('saving', 'Saving...');

            $.ajax({
                url: "addPayment.php",
                type: 'POST',
                data: {
                    action: 'autoSavePayments',
                    format: 'json',
                    serviceType: serviceTypeArray.join("~"),
                    decidedAmount: serviceAmountArray.join("~"),
                    paymentReceived: paymentReceivedArray.join("~"),
                    tdsAmount: tdsAmountArray.join("~"),
                    discountAmount: discountAmountArray.join("~"),
                    depositDate: depositDateArray.join("~"),
                    chequeDetails: serviceChequeArray.join("~"),
                    reconciliation: reconciliationArray.join("~"),
                    customer: customerID,
                    payid: paymentID,
                    rowids: rowidArray.join("~"),
                    dltRows: ""
                },
                dataType: 'json',
                success: function (res) {
                    if (res && res.success) {
                        if (res.payid) {
                            $('#paymentAutoSaveStatus').attr('data-row-id', res.payid);
                            $('.savePayment').attr('data-row-id', res.payid);
                        }
                        if (res.rowIds && Array.isArray(res.rowIds)) {
                            for (var k = 0; k < res.rowIds.length; k++) {
                                var newId = res.rowIds[k];
                                if (newId && newId > 0 && $matchedRows[k]) {
                                    $matchedRows[k].find('.row-id').val(newId);
                                    $matchedRows[k].find('.toggleReconcileBtn').attr('data-pay-id', newId);
                                    $matchedRows[k].find('.infoDelete').attr('data-row-id', newId);
                                    $matchedRows[k].find('.serviceBlockTypeSelect').attr('data-pay-id', newId);
                                }
                            }
                        }
                        showAutoSaveIndicator('saved');
                    } else {
                        showAutoSaveIndicator('error', (res && res.message) ? res.message : 'Save error');
                    }
                },
                error: function () {
                    showAutoSaveIndicator('error', 'Save error');
                },
                complete: function () {
                    isPaymentSaving = false;
                    if (paymentSavePending) {
                        paymentSavePending = false;
                        triggerPaymentAutoSave(false);
                    }
                }
            });
        }

        // Auto-save triggers on typing, changing, or blurring payment fields
        $(document).on('input', '.servicePaymentReceived, .serviceTdsAmount, .serviceDiscountAmount, .serviceChequeDetails', function () {
            recalculatePaymentSystem();
            triggerPaymentAutoSave(false);
        });

        $(document).on('change blur', '.servicePaymentReceived, .serviceTdsAmount, .serviceDiscountAmount, .paymentDepositDate, .serviceChequeDetails', function () {
            recalculatePaymentSystem();
            triggerPaymentAutoSave(true);
        });

        // Prevent editing ANY field of a reconciled / locked payment entry and alert the user
        $(document).on('click focus keydown mousedown', '.reconciled-locked-input, input[data-reconciled="1"], .servicePaymentReceived[data-reconciled="1"], .serviceTdsAmount[data-tds-locked="1"], .serviceTdsAmount[data-reconciled="1"], .tds-locked-input, .paymentDepositDate[data-reconciled="1"], .serviceChequeDetails[data-reconciled="1"], tr.row-reconciled-locked input', function (e) {
            e.preventDefault();
            $(this).blur();
            if (typeof Swal !== 'undefined') {
                Swal.fire({
                    icon: 'warning',
                    title: '<span style="font-size: 18px; font-weight: 700; color: #b45309;"><i class="fa fa-lock" style="margin-right: 6px;"></i> Reconciled Entry</span>',
                    html: '<div style="font-size: 13.5px; color: #334155;">Cannot edit reconciled payment entry.<br><small style="color: #64748b;">This payment entry has been verified/reconciled against bank records.</small></div>',
                    confirmButtonColor: '#0d4d8b',
                    confirmButtonText: 'OK'
                });
            } else {
                alert('Cannot edit reconciled payment entry.');
            }
            return false;
        });

        // Delegate deletion for all payment rows with auto-save & recalculation
        $(document).on('click', '.infoDelete', function (e) {
            e.preventDefault();
            e.stopPropagation();
            var $btn = $(this);
            var payrowid = $btn.attr('data-row-id');
            var $row = $btn.closest('tr');
            if (!payrowid) {
                payrowid = $row.find('.row-id').val();
            }

            var isLocked = ($btn.attr('data-tds-locked') === '1' || $btn.attr('data-reconciled') === '1' || $row.find('.serviceTdsAmount[data-tds-locked="1"]').length > 0 || $row.find('.tds-locked-input').length > 0 || $row.hasClass('row-reconciled-locked') || $row.find('.serviceReconciliation').val() === 'Verified');
            if (isLocked) {
                if (typeof Swal !== 'undefined') {
                    Swal.fire({
                        icon: 'error',
                        title: '<span style="font-size: 18px; font-weight: 700; color: #dc2626;"><i class="fa fa-ban" style="margin-right: 6px;"></i> Action Prohibited</span>',
                        html: '<div style="font-size: 13.5px; color: #334155; line-height: 1.5;"><strong>Cannot delete payment that is verified by accounts person and reconciled from bank statement.</strong></div>',
                        confirmButtonColor: '#0d4d8b',
                        confirmButtonText: 'OK'
                    });
                } else {
                    alert('Cannot delete payment that is verified by accounts person and reconciled from bank statement.');
                }
                return false;
            }

            if (!payrowid || payrowid === '0') {
                $row.remove();
                if (typeof recalculatePaymentSystem === 'function') recalculatePaymentSystem();
                return;
            }

            if (confirm("Are you sure you want to delete this payment record?")) {
                showAutoSaveIndicator('saving', 'Deleting...');
                $.ajax({
                    url: "addPayment.php",
                    type: "GET",
                    data: { paymentID: payrowid },
                    success: function (resp) {
                        if (resp && resp.indexOf('cannot') !== -1) {
                            alert(resp);
                            showAutoSaveIndicator('error', 'Cannot delete');
                            return;
                        }
                        $row.remove();
                        if (typeof recalculatePaymentSystem === 'function') recalculatePaymentSystem();
                        showAutoSaveIndicator('saved', 'Deleted');
                        setTimeout(function () { showAutoSaveIndicator('saved'); }, 2000);
                    },
                    error: function () {
                        showAutoSaveIndicator('error', 'Delete error');
                    }
                });
            }
        });

        $(document).on('click', '.removeNewPaymentRow', function (e) {
            e.preventDefault();
            var $row = $(this).closest('tr');
            var payrowid = $row.find('.row-id').val();
            var isLocked = ($row.find('.serviceTdsAmount[data-tds-locked="1"]').length > 0 || $row.find('.tds-locked-input').length > 0 || $row.hasClass('row-reconciled-locked') || $row.find('.serviceReconciliation').val() === 'Verified');
            if (isLocked) {
                if (typeof Swal !== 'undefined') {
                    Swal.fire({
                        icon: 'error',
                        title: '<span style="font-size: 18px; font-weight: 700; color: #dc2626;"><i class="fa fa-ban" style="margin-right: 6px;"></i> Action Prohibited</span>',
                        html: '<div style="font-size: 13.5px; color: #334155; line-height: 1.5;"><strong>Cannot delete payment that is verified by accounts person and reconciled from bank statement.</strong></div>',
                        confirmButtonColor: '#0d4d8b',
                        confirmButtonText: 'OK'
                    });
                } else {
                    alert('Cannot delete payment that is verified by accounts person and reconciled from bank statement.');
                }
                return false;
            }
            if (payrowid && payrowid !== '0') {
                if (confirm("Are you sure you want to delete this payment row?")) {
                    showAutoSaveIndicator('saving', 'Deleting...');
                    $.ajax({
                        url: "addPayment.php",
                        type: "GET",
                        data: { paymentID: payrowid },
                        success: function (resp) {
                            if (resp && resp.indexOf('Cannot delete payment') !== -1) {
                                if (typeof Swal !== 'undefined') {
                                    Swal.fire({
                                        icon: 'error',
                                        title: 'Action Prohibited',
                                        text: resp,
                                        confirmButtonColor: '#0d4d8b'
                                    });
                                } else {
                                    alert(resp);
                                }
                                showAutoSaveIndicator('error', 'Cannot delete');
                                return;
                            }
                            $row.remove();
                            if (typeof recalculatePaymentSystem === 'function') recalculatePaymentSystem();
                            showAutoSaveIndicator('saved', 'Deleted');
                            setTimeout(function () { showAutoSaveIndicator('saved'); }, 2000);
                        },
                        error: function () {
                            showAutoSaveIndicator('error', 'Delete error');
                        }
                    });
                }
            } else {
                $row.remove();
                if (typeof recalculatePaymentSystem === 'function') recalculatePaymentSystem();
            }
        });

        $(document).off('submit.customerAccount', '#informationUpdationReviewForm');
        $(document).on('submit.customerAccount', '#informationUpdationReviewForm', function (e) {
            e.preventDefault();

            var $form = $(this);
            var reviewDateStr = $form.find('input[name="review_date"]').val();
            var suspendDateStr = $form.find('#info_review_suspend_date').val();
            
            if (!suspendDateStr) {
                console.log("DEBUG ERROR: There is no Suspension Date attached to this button! (Value is empty).");
            }
            
            if (reviewDateStr && suspendDateStr) {
                var rParts;
                if (reviewDateStr.indexOf('.') !== -1) rParts = reviewDateStr.split('.');
                else if (reviewDateStr.indexOf('-') !== -1) rParts = reviewDateStr.split('-');
                else if (reviewDateStr.indexOf('/') !== -1) rParts = reviewDateStr.split('/');
                
                var reviewDate = new Date(rParts[2], rParts[1] - 1, rParts[0]);
                
                var sParts, suspendDate;
                if (suspendDateStr.indexOf('-') !== -1) {
                    sParts = suspendDateStr.split('-');
                    suspendDate = new Date(sParts[0], sParts[1] - 1, sParts[2]);
                } else if (suspendDateStr.indexOf('.') !== -1) {
                    sParts = suspendDateStr.split('.');
                    suspendDate = new Date(sParts[2], sParts[1] - 1, sParts[0]);
                } else {
                    suspendDate = new Date(suspendDateStr);
                }
                
                var minDate = new Date(suspendDate);
                minDate.setMonth(minDate.getMonth() - 2);
                
                if (isNaN(reviewDate.getTime()) || isNaN(minDate.getTime())) {
                    alert("DEBUG ERROR: Invalid date format entered. Cannot validate. reviewDate: " + reviewDateStr + ", suspendDate: " + suspendDateStr);
                    return false;
                }
                
                if (reviewDate < minDate) {
                    var d = minDate.getDate();
                    var m = minDate.getMonth() + 1;
                    var formattedSuspendDate = (d < 10 ? '0' : '') + d + '.' + (m < 10 ? '0' : '') + m + '.' + minDate.getFullYear();
                    var errorMsg = 'Information Update Submission Date must be on or after ' + formattedSuspendDate + ' (within 2 months of the Suspension Date).';
                    
                    $form.find('#info_review_date_error')
                        .text(errorMsg)
                        .show();
                    return false;
                }
            }
            
            $form.find('#info_review_date_error').hide().text('');

            var formData = new FormData(this);
            formData.append('action', 'saveInfoUpdationReview');
            var serviceId = $('input[name="info_review_service_id"]').val();
            var customerId = $('input[name="info_review_customer_id"]').val();

            $.ajax({
                url: 'saveInfoUpdationReview.php',
                type: 'POST',
                data: formData,
                processData: false,
                contentType: false,
                dataType: 'json', // Expect JSON response
                success: function (response) {
                    console.log('Response:', response); // Debug log
                    if (response && response.success) {
                        // Find the icon container for this specific service
                        var $iconLink = $('.openInfoUpdationReview[data-service="' + serviceId + '"]');
                        var $iconContainer = $iconLink.parent();

                        // Check if this was a plus icon (new entry)
                        var wasPlus = $iconLink.find('i').hasClass('fa-plus-circle');

                        if (wasPlus) {
                            // Change plus icon to pencil icon
                            $iconLink.find('i').removeClass('fa-plus-circle').addClass('fa-pencil-square');
                            $iconLink.attr('title', 'Review Information Updation');

                            // Add download icon after pencil icon (without disabled class)
                            var downloadHtml = '<span style="padding-right: 5px">' +
                                '<a class="downloadInfoUpdationReview pull-right" ' +
                                'data-customer="' + customerId + '" data-service="' + serviceId + '" ' +
                                'title="Download Information Updation Review" style="padding: 1px 5px;">' +
                                '<i class="fa fa-download fa-lg " style="padding: 3px"></i></a></span>';

                            $iconLink.parent().after(downloadHtml);
                        }

                        // Change the section color to blue by updating the CSS class
                        // Find the parent div that contains the serviceContent class
                        var $sectionDiv = $iconLink.closest('div[class*="serviceContent"]');

                        // Remove existing service content classes and add completed class
                        $sectionDiv.removeClass('serviceContent serviceContentwaiting');
                        $sectionDiv.addClass('serviceContentCompleted');

                        $('#informationUpdationReviewModal').modal('hide');
                        alert('Review saved successfully!');

                        // Don't reload the page - UI is already updated
                    } else {
                        alert('Error saving review: ' + (response.error || 'Unknown error'));
                    }
                },
                error: function (xhr, status, error) {
                    console.error('Error response:', xhr.responseText);
                    console.error('Status:', status);
                    console.error('Error:', error);

                    // Try to parse error response
                    var errorMessage = 'Error saving review: ';
                    try {
                        var errorData = JSON.parse(xhr.responseText);
                        errorMessage += errorData.error || error;
                    } catch (e) {
                        // If response is not JSON, show the HTML error
                        if (xhr.responseText.length > 200) {
                            errorMessage += 'Server error. Check console for details.';
                            console.error('Full error response:', xhr.responseText);
                        } else {
                            errorMessage += xhr.responseText || error;
                        }
                    }
                    alert(errorMessage);
                }
            });
        });


